// Shared Rust-only snapshot format. Expectations are never generated by Crystal.
use crate::hir::{Class, Hir, HirKind, LookSet};
use std::{
    format,
    string::{String, ToString},
    vec::Vec,
};
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
fn bits(set: LookSet) -> u32 {
    let mut bytes = [0; 4];
    set.write_repr(&mut bytes);
    u32::from_ne_bytes(bytes)
}
fn optional(value: Option<usize>) -> String {
    value.map_or_else(|| "-".into(), |v| v.to_string())
}
fn shape(h: &Hir) -> String {
    match h.kind() {
        HirKind::Empty => "empty".into(),
        HirKind::Literal(l) => format!("lit({})", hex(&l.0)),
        HirKind::Look(l) => format!("look({})", *l as u32),
        HirKind::Class(Class::Unicode(c)) => format!(
            "unicode({})",
            c.iter()
                .map(|r| format!("{}-{}", r.start() as u32, r.end() as u32))
                .collect::<Vec<_>>()
                .join(",")
        ),
        HirKind::Class(Class::Bytes(c)) => format!(
            "bytes({})",
            c.iter()
                .map(|r| format!("{}-{}", r.start(), r.end()))
                .collect::<Vec<_>>()
                .join(",")
        ),
        HirKind::Capture(c) => format!(
            "cap({},{},{})",
            c.index,
            c.name
                .as_ref()
                .map_or_else(|| "-".into(), |n| hex(n.as_bytes())),
            shape(&c.sub)
        ),
        HirKind::Repetition(r) => format!(
            "rep({},{},{},{})",
            r.min,
            r.max.map_or_else(|| "-".into(), |v| v.to_string()),
            r.greedy,
            shape(&r.sub)
        ),
        HirKind::Concat(c) => format!("cat({})", c.iter().map(shape).collect::<Vec<_>>().join(",")),
        HirKind::Alternation(c) => {
            format!("alt({})", c.iter().map(shape).collect::<Vec<_>>().join(","))
        }
    }
}
fn properties(p: &crate::hir::Properties) -> String {
    format!(
        "{}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}",
        optional(p.minimum_len()),
        optional(p.maximum_len()),
        p.is_utf8(),
        p.explicit_captures_len(),
        optional(p.static_explicit_captures_len()),
        p.is_literal(),
        p.is_alternation_literal(),
        bits(p.look_set()),
        bits(p.look_set_prefix()),
        bits(p.look_set_prefix_any()),
        bits(p.look_set_suffix()),
        bits(p.look_set_suffix_any())
    )
}
fn snapshot(h: &Hir) -> String {
    format!("{}\n{}\n{}", shape(h), h, properties(h.properties()))
}
pub fn record_properties(t: &super::Translator, pattern: &str, p: &crate::hir::Properties) {
    record_value(t, pattern, properties(p));
}
pub fn record(t: &super::Translator, pattern: &str, result: &super::Result<Hir>) {
    let expected = match result {
        Ok(hir) => snapshot(hir),
        Err(e) => format!(
            "error({:?},{},{},{},{},{},{})",
            e.kind(),
            e.span().start.offset,
            e.span().start.line,
            e.span().start.column,
            e.span().end.offset,
            e.span().end.line,
            e.span().end.column
        ),
    };
    record_value(t, pattern, expected);
}
fn record_value(t: &super::Translator, pattern: &str, expected: String) {
    use std::io::Write;
    let path = std::env::var("REGEX_PARITY_CAPTURE").unwrap();
    let flags = t.flags.get();
    let config = format!(
        "{},{},{},{},{},{},{},{}",
        t.utf8,
        t.line_terminator,
        flags.case_insensitive(),
        flags.multi_line(),
        flags.dot_matches_new_line(),
        flags.swap_greed(),
        flags.unicode(),
        flags.crlf()
    );
    let thread = std::thread::current();
    let name = thread.name().unwrap();
    let mut file = std::fs::OpenOptions::new()
        .append(true)
        .create(true)
        .open(path)
        .unwrap();
    writeln!(
        file,
        "{}\t{}\t{}\t{}",
        name,
        config,
        hex(pattern.as_bytes()),
        hex(expected.as_bytes())
    )
    .unwrap();
}
pub fn assertion(line: u32) {
    use std::io::Write;
    let mut file = std::fs::OpenOptions::new()
        .append(true)
        .create(true)
        .open(std::env::var("REGEX_PARITY_ASSERTIONS").unwrap())
        .unwrap();
    writeln!(file, "{}\t{}", std::thread::current().name().unwrap(), line).unwrap();
}
